begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
create temporary table past_clock(instant timestamptz);
insert into past_clock values('2026-03-10 12:00:00+00');
create or replace function private.progress_time() returns timestamptz language sql volatile set search_path='' as $$select instant from pg_temp.past_clock$$;
create function pg_temp.clock_at(stamp timestamptz) returns void language sql as $$update pg_temp.past_clock set instant=stamp$$;
create function pg_temp.challenge(day date) returns uuid language plpgsql as $$
declare c uuid;
begin
 insert into public.daily_challenges(user_id,user_language_profile_id,created_at)
  select user_id,id,(day::timestamp+interval '12 hours') at time zone timezone from public.user_language_profiles where user_id=auth.uid() returning id into c;
 perform private.assign_challenge_word(c,'review');perform private.assign_challenge_word(c,'target');perform private.assign_challenge_word(c,'stretch');
 return c;
end;$$;
create function pg_temp.complete(sid uuid,which_visibility text default 'private') returns uuid language plpgsql as $$
declare s public.submissions;o storage.objects;
begin
 select * into strict s from public.submissions where id=sid;
 if s.status='completed' then perform public.finalize_submission(sid,which_visibility);return sid;end if;
 insert into storage.objects(bucket_id,name,owner_id,version,metadata)
  values('challenge-submissions',s.storage_path,s.user_id::text,'past-word-fixture','{"mimetype":"image/jpeg","size":100}') returning * into o;
 -- Real bytes and the Edge verifier are covered separately by Auth/Storage tests.
 perform public.attest_submission_photo(s.id,s.user_id,o.id,o.version,repeat('a',64),16,16);
 perform public.finalize_submission(s.id,which_visibility);return s.id;
end;$$;
create function pg_temp.erase(sid uuid) returns void language plpgsql as $$
begin
 perform public.begin_submission_deletion(sid);
 perform set_config('storage.allow_delete_query','true',true);
 delete from storage.objects where name=(select storage_path from public.submissions where id=sid);
 perform public.finish_submission_deletion(sid);
end;$$;
insert into auth.users(id,email) values
