update assignments set id=(select w.id from public.daily_challenge_words w where w.daily_challenge_id=assignments.daily_challenge_id and w.slot=assignments.slot and w.replaced_at is null) where label='old' and slot='target';
insert into captures values('old-review',(public.reserve_historical_submission((select id from assignments where label='old' and slot='review'))).id);
