select is((select payload->>'has_more' from pages),'true','Bounded Past Words pages advertise more');
select is(jsonb_array_length((select public.get_my_past_words(before_captured=>(payload->'items'->1->>'has_capture')::boolean,before_date=>(payload->'items'->1->>'challenge_date')::date,before_id=>(payload->'items'->1->>'assignment_id')::uuid,page_size=>2)->'items' from pages)),2,'Keyset crosses missing/captured partitions without dropping rows');
select is(jsonb_array_length(public.get_my_past_words(search_text=>upper((select target_term from public.daily_challenge_words where id=(select id from assignments where label='old' and slot='review'))))->'items')>=1,true,'Search is case-insensitive over immutable target snapshots');
